INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('junjo-romantica-1er9','Junjo Romantica','純情ロマンチカ',2008,7.5,'Spring 2008','TV','Finished','https://media.kitsu.app/anime/poster_images/2788/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/3092-g60dQLpR39ra.jpg','#ff1f4a','Misaki Takahashi is a regular high school student who is preparing for his university entrance exams. In order to reduce the stress of studying, or so he hopes, he accepts the help of his older brother''s best friend, and famous author, Akihiko Usami. However, Masaki is about to find out that Usami''s books are of a very naughty genre, and that there may be something naughty waking up inside Masaki as well.Junjou Romantica also follows the story of two other couples loosely connected to Masaki and Usami''s "Romantica." Egoist shows the very passionate, but often complicated, relationship between university professor Hiroki Kamijou (whose life has reached an all time low) and paediatrician Nowaki Kusama, who falls for Hiroki at first sight and would do anything to make him happy. The third story, "Terrorist," shows just how obsessive love can become when rich eighteen-year-old Shinobu Takatsuki finally discovers something that he cannot have so easily—the literature professor You Miyagi. There is passion abound as these three couples try to achieve their goals in life while also falling into temptation and anguish with their partners.',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":2788,"anilist":3092,"mal":3092}',NULL,NULL,12,datetime('now'),'junjo romantica 純情ロマンチカ tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;

