INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#1','junjo-romantica-1er9',1,'Truth Is Stranger Than Fiction','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47281/original.jpg','Misaki doesn''t have the best grades, so his brother, Takahiro, sets him up to live with his childhood friend, Akihito Usami, to be tutored so Misaki can get into college. Akihito is a top-selling, award-winning novelist. So, one day Misaki decides to check out one of the best-selling novels. Misaki discovers that Akihito writes boy-love books! And if that''s not bad enough, his brother''s name is one of the leading roles! Just what kind of relationship does this Akihito and Misaki''s beloved older brother, Takahiro, have with each other?','[]','2008-04-10','47281');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#2','junjo-romantica-1er9',2,'There''s No Use Crying over Spilt Milk','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47282/original.jpg','Misaki has now been living with Akihito for a month. They get along smashingly…Especially since they are developing somewhat of a relationship. How exactly will Misaki cope with having his name be the new star of Akihito''s romance novels? And how will Akihito deal with his overwhelming jealousy growing from Misaki''s classmate?','[]','2008-04-16','47282');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#3','junjo-romantica-1er9',3,'Knock, and It Shall Be Opened to You','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47283/original.jpg','Meet Hiroki. He is Akihito''s childhood friend and totally and completely in love with him. The only problem is that Akihito doesn''t love him back. In fact, he is unaware of his feelings. So, in an attempt to convey his feelings to Akihito, Hiroki sleeps with him. The problem is, though, Akihito still doesn''t notice. But, with the help of a younger man named Nowaki, Hiroki just might be able to regain the wonderful feeling of being in love.','[]','2008-04-24','47283');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#4','junjo-romantica-1er9',4,'The Fear Is Often Greater Than the Danger Itself','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47284/original.jpg','Misaki meets Akihito''s editor, Eri Aikawa, and gets extremely jealous over how well she knows Akihito. Misaki''s classmate really doesn''t help matters when he points out that an editor shouldn''t be close to Akihito like that. So, how will Misaki get over his complex?','[]','2008-05-01','47284');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#5','junjo-romantica-1er9',5,'Meeting in the beginning of parting','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47285/original.jpg','6 years later…Nowaki and Hiroki are still in love with each other. But, how far will their love go when Nowaki leaves for America without even telling Hiroki?','[]','2008-05-08','47285');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#6','junjo-romantica-1er9',6,'Turning a Misfortune into a Blessing','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47286/original.jpg','Nowaki knows that he loves Hiroki, and Hiroki know the feelings are mutual. Even though they had some problems they agree to meet up and talk things out…But what is Hiroki supposed to do when Nowaki stands him up? How could Nowaki agree to a business meeting that interferes with his love-life? Can their love go on?','[]','2008-05-15','47286');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#7','junjo-romantica-1er9',7,'Spare the rod and spoil the child','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47287/original.jpg','Misaki is questioning whether Akihito and he are classified as "lovers". Of course, Akihito just won''t have that, so Akihito takes Misaki on a date.','[]','2008-05-22','47287');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#8','junjo-romantica-1er9',8,'Travelers Have No Need for Shame','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47288/original.jpg','Takahiro calls and tells Akihito that it''s time Misaki comes to live with his new wife and him. Akihito really doesn''t want to let Misaki leave, but Misaki never has experienced a family life, so there is no way he would refuse. So, can Akihito and Misaki go back to not living with each other?','[]','2008-05-29','47288');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#9','junjo-romantica-1er9',9,'Tenderness Is Not Just for the Sake of Others','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47289/original.jpg','Hiroki takes a stroll down memory lane and recalls his first meeting with Akihito…and how he fell in love with him.','[]','2008-06-05','47289');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#10','junjo-romantica-1er9',10,'Young Men, Be Bold','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47290/original.jpg','You Miyagi is a coworker of Hiroki. He really enjoys making fun of Hiroki and his boy-love relationship…but how will he react when he gets a boy-love relationship of his own? You is a divorcee who just can''t seem to get rid of his ex-brother-in-law. How can he get rid of this guy who claims they are fated to be together?','[]','2008-06-12','47290');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#11','junjo-romantica-1er9',11,'You Tend to Do Well at the Things You Enjoy','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47291/original.jpg','You Miyagi and Shinobuc have more in common than Miyagi first thought. Their impossible relationship is just to similar to one in his past…Is there any hope for these so called "fated" lovers?','[]','2008-06-19','47291');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('junjo-romantica-1er9#12','junjo-romantica-1er9',12,'There''s No Such Thing as a Chance Encounter','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/47292/original.jpg','Akihito just won an award for his latest BL book. And Misaki is unhappy that he learned this bit of information from his classmate instead of Akihito. That leads to Misaki blowing up on Akihito about how he deserves to know more about him since they are lovers.','[]','2008-06-26','47292');

